"use client"

import { motion, useScroll, useTransform, useReducedMotion } from "motion/react"

/**
 * "Sacred Journey Through The Temple" — Tag 1 Upgrade
 *
 * Changes vs. original:
 *  - Temple 3–5× more visible (opacity 0.28–0.55, was 0.11–0.16)
 *  - Crepuscular light rays fan out from finial (appear as mist clears)
 *  - Stronger background glow
 *  - Finial halo bloom effect
 *  - Mist clears faster (40% instead of 65%)
 *  - Bolder gable finials on every roof tier
 */
export default function TempleJourney() {
  const prefersReduced = useReducedMotion()
  const { scrollYProgress } = useScroll()

  const nm = ["0px", "0px"] as [string, string]

  // ── Zoom: temple already fills the screen at start ──────────────────────
  const scale = useTransform(
    scrollYProgress, [0, 1],
    prefersReduced ? [1, 1] : [0.88, 2.6]
  )

  // ── Background glow: strong from the very beginning ─────────────────────
  const glowOpacity = useTransform(scrollYProgress, [0, 0.4, 1], [0.38, 0.55, 0.72])

  // ── No mist at start — temple is immediately visible ────────────────────
  const mistOpacity = useTransform(
    scrollYProgress, [0, 0.3],
    prefersReduced ? [0.1, 0.1] : [0.08, 0]
  )

  // ── Temple at near-full opacity from the very first frame ───────────────
  const templeVisible = useTransform(scrollYProgress, [0, 0.5, 1], [0.92, 0.96, 1.0])

  // ── Derived per-layer opacities ──────────────────────────────────────────
  const monoOpacity   = useTransform(templeVisible, v => v * 0.60)
  const baseOpacity   = useTransform(templeVisible, v => v * 0.78)
  const bodyOpacity   = useTransform(templeVisible, v => v * 0.78)
  const spireOpacity  = useTransform(templeVisible, v => v * 0.92)

  // ── Light rays: appear as mist clears, peak mid-scroll ──────────────────
  const raysOpacity = useTransform(
    scrollYProgress,
    [0.06, 0.28, 0.62, 1],
    prefersReduced ? [0, 0, 0, 0] : [0, 0.78, 0.92, 0.5]
  )

  // ── Swoosh fades as you start scrolling ─────────────────────────────────
  const swooshOp = useTransform(scrollYProgress, [0, 0.38], [1, 0])

  // ── Per-layer Y parallax ─────────────────────────────────────────────────
  const yMono   = useTransform(scrollYProgress, [0, 1], prefersReduced ? nm : ["0px", "-65px"])
  const yBase   = useTransform(scrollYProgress, [0, 1], prefersReduced ? nm : ["0px", "-130px"])
  const yBody   = useTransform(scrollYProgress, [0, 1], prefersReduced ? nm : ["0px", "-205px"])
  const ySpire  = useTransform(scrollYProgress, [0, 1], prefersReduced ? nm : ["0px", "-318px"])
  const ySwoosh = useTransform(scrollYProgress, [0, 1], prefersReduced ? nm : ["0px", "-88px"])

  const svgBase = {
    width: 700, height: 700,
    viewBox: "0 0 400 420",
    fill: "none",
    xmlns: "http://www.w3.org/2000/svg",
  }

  // ── Crepuscular ray params ───────────────────────────────────────────────
  // Finial is at approx (286, 48) in viewBox coords.
  // Rays fan 150° upward (-155° → -5° from x-axis).
  const rays = [
    { a: -155, w: 5,  l: 155 },
    { a: -138, w: 7,  l: 172 },
    { a: -120, w: 10, l: 192 },
    { a: -105, w: 14, l: 210 },
    { a:  -90, w: 20, l: 235 },  // central bright ray
    { a:  -75, w: 14, l: 210 },
    { a:  -60, w: 10, l: 192 },
    { a:  -42, w: 7,  l: 172 },
    { a:  -25, w: 5,  l: 155 },
  ]

  return (
    <div
      aria-hidden="true"
      className="fixed inset-0 flex items-center justify-center pointer-events-none select-none overflow-hidden"
      style={{ zIndex: -1 }}
    >
      {/* ── Layer 0: Background radial gold glow ── */}
      <motion.div
        className="absolute inset-0"
        style={{
          background:
            "radial-gradient(ellipse 62% 68% at 50% 50%, rgba(201,168,76,0.88), transparent 72%)",
          opacity: glowOpacity,
        }}
      />

      {/* ── Scale wrapper ── */}
      <motion.div
        className="relative"
        style={{ scale, width: 700, height: 700 }}
      >

        {/* ── Layer 1: TA Monogram ── */}
        <motion.div
          className="absolute inset-0 flex items-center justify-center"
          style={{ y: yMono }}
        >
          <motion.svg {...svgBase} style={{ opacity: monoOpacity }}>
            {/* T — Gold */}
            <rect x="30" y="170" width="210" height="26" rx="6" fill="#C9A84C" />
            <rect x="108" y="170" width="54" height="215" rx="6" fill="#C9A84C" />
            <path
              d="M 220 170 C 255 155 290 120 310 85 C 320 68 305 58 288 68 C 265 82 240 115 220 145"
              stroke="#C9A84C" strokeWidth="18" fill="none" strokeLinecap="round"
            />
            {/* A — Silver */}
            <path d="M 195 385 L 258 170 L 282 170 L 345 385 Z" fill="#E0E0E0" opacity="0.94" />
            <path d="M 215 385 L 268 210 L 282 210 L 326 385 Z" fill="#0A0A0A" opacity="0.65" />
            <rect x="228" y="290" width="114" height="22" rx="5" fill="#E0E0E0" opacity="0.94" />
          </motion.svg>
        </motion.div>

        {/* ── Layer 2: Temple Base Platform ── */}
        <motion.div
          className="absolute inset-0 flex items-center justify-center"
          style={{ y: yBase }}
        >
          <motion.svg {...svgBase} style={{ opacity: baseOpacity }}>
            {/* Lowest step */}
            <rect x="228" y="276" width="114" height="16" rx="4" fill="#C9A84C" />
            {/* Step 1 */}
            <path d="M 220 276 L 352 276 L 342 258 L 230 258 Z" fill="#C9A84C" />
            {/* Step 2 */}
            <path d="M 228 258 L 344 258 L 335 242 L 237 242 Z" fill="#D4A840" />
            {/* Decorative columns */}
            <rect x="232" y="242" width="7" height="35" rx="2" fill="#E0B850" />
            <rect x="333" y="242" width="7" height="35" rx="2" fill="#E0B850" />
            {/* Column caps */}
            <rect x="229" y="238" width="13" height="5" rx="1" fill="#F0CE60" />
            <rect x="330" y="238" width="13" height="5" rx="1" fill="#F0CE60" />
            {/* Base trim line */}
            <path d="M 215 276 L 357 276" stroke="#E8C866" strokeWidth="1.5" strokeLinecap="round" opacity="0.5" />
          </motion.svg>
        </motion.div>

        {/* ── Layer 3: Temple Roof Tiers + Main Body ── */}
        <motion.div
          className="absolute inset-0 flex items-center justify-center"
          style={{ y: yBody }}
        >
          <motion.svg {...svgBase} style={{ opacity: bodyOpacity }}>
            {/* Roof tier 1 — widest */}
            <path d="M 233 242 L 339 242 L 327 224 L 245 224 Z" fill="#C9A84C" />
            {/* Gable finials tier 1 */}
            <path d="M 233 242 L 245 224 L 238 232 Z" fill="#F0CE60" />
            <path d="M 339 242 L 327 224 L 334 232 Z" fill="#F0CE60" />

            {/* Roof tier 2 */}
            <path d="M 245 224 L 327 224 L 315 207 L 257 207 Z" fill="#C9A84C" />
            {/* Gable finials tier 2 */}
            <path d="M 245 224 L 257 207 L 250 215 Z" fill="#F0CE60" />
            <path d="M 327 224 L 315 207 L 322 215 Z" fill="#F0CE60" />

            {/* Roof tier 3 */}
            <path d="M 256 207 L 316 207 L 304 191 L 268 191 Z" fill="#D4A840" />
            {/* Gable finials tier 3 */}
            <path d="M 256 207 L 268 191 L 261 199 Z" fill="#F0CE60" />
            <path d="M 316 207 L 304 191 L 311 199 Z" fill="#F0CE60" />

            {/* Roof tier 4 */}
            <path d="M 266 191 L 306 191 L 295 176 L 277 176 Z" fill="#D4A840" />
            {/* Gable finials tier 4 */}
            <path d="M 266 191 L 277 176 L 270 183 Z" fill="#F0CE60" />
            <path d="M 306 191 L 295 176 L 302 183 Z" fill="#F0CE60" />

            {/* Tower shaft */}
            <rect x="278" y="157" width="16" height="22" rx="3" fill="#E0B84C" />

            {/* Decorative rings on tower */}
            <rect x="273" y="152" width="26" height="5" rx="2" fill="#E8C866" />
            <rect x="275" y="146" width="22" height="5" rx="2" fill="#E8C866" />
          </motion.svg>
        </motion.div>

        {/* ── Layer 4: Spire + Finial + Crepuscular Rays ── */}
        <motion.div
          className="absolute inset-0 flex items-center justify-center"
          style={{ y: ySpire }}
        >
          <motion.svg {...svgBase}>
            <defs>
              {/* Ray gradient: bright at finial, fades to transparent */}
              <linearGradient id="tvRayGrad" x1="0" y1="0" x2="0" y2="1" gradientUnits="userSpaceOnUse">
                <stop offset="0%" stopColor="#FFF4B0" stopOpacity="0" />
                <stop offset="25%" stopColor="#F5DA66" stopOpacity="0.9" />
                <stop offset="100%" stopColor="#C9A84C" stopOpacity="0" />
              </linearGradient>
              {/* Halo glow */}
              <radialGradient id="tvHaloGrad" cx="286" cy="50" r="45" gradientUnits="userSpaceOnUse">
                <stop offset="0%" stopColor="#FFF8C0" stopOpacity="0.55" />
                <stop offset="50%" stopColor="#F0CE60" stopOpacity="0.2" />
                <stop offset="100%" stopColor="#C9A84C" stopOpacity="0" />
              </radialGradient>
            </defs>

            {/* ── CREPUSCULAR RAYS (behind spire) ── */}
            <motion.g style={{ opacity: raysOpacity }}>
              {rays.map((r, i) => {
                const rad = (r.a * Math.PI) / 180
                return (
                  <line
                    key={i}
                    x1="286" y1="48"
                    x2={286 + Math.cos(rad) * r.l}
                    y2={48 + Math.sin(rad) * r.l}
                    stroke="url(#tvRayGrad)"
                    strokeWidth={r.w}
                    strokeLinecap="round"
                  />
                )
              })}
              {/* Extra subtle outer bloom */}
              {rays.filter((_, i) => i === 4).map((r, i) => {
                const rad = (r.a * Math.PI) / 180
                return (
                  <line
                    key={`bloom-${i}`}
                    x1="286" y1="48"
                    x2={286 + Math.cos(rad) * 290}
                    y2={48 + Math.sin(rad) * 290}
                    stroke="#F0CE60"
                    strokeWidth={38}
                    strokeLinecap="round"
                    opacity={0.06}
                  />
                )
              })}
            </motion.g>

            {/* ── Halo bloom around finial ── */}
            <motion.ellipse
              cx="286" cy="50"
              rx="44" ry="42"
              fill="url(#tvHaloGrad)"
              style={{ opacity: raysOpacity }}
            />

            {/* ── Spire body ── */}
            <motion.g style={{ opacity: spireOpacity }}>
              {/* Lower spire taper */}
              <path d="M 274 146 L 298 78 L 300 146 Z" fill="#F0CE60" />
              {/* Mid spire */}
              <path d="M 281 78 L 286 40 L 291 78 Z" fill="#F5DA66" />
              {/* Upper spire */}
              <path d="M 283 40 L 286 12 L 289 40 Z" fill="#FFF8CC" />

              {/* Finial sphere (large) */}
              <circle cx="286" cy="62" r="15" fill="#F5D860" />
              {/* Finial sphere (mid) */}
              <circle cx="286" cy="46" r="9.5" fill="#FFF0A0" />
              {/* Finial top */}
              <circle cx="286" cy="34" r="5.5" fill="#FFFFFF" opacity="0.96" />
              {/* Very tip */}
              <circle cx="286" cy="9" r="3.5" fill="#FFFFFF" opacity="0.9" />
              <line x1="286" y1="28" x2="286" y2="9" stroke="#FFFFFF" strokeWidth="2.5" strokeLinecap="round" opacity="0.85" />

              {/* Decorative rings at tower/spire junction */}
              <rect x="275" y="140" width="22" height="5" rx="2" fill="#E8C866" />
              <rect x="276" y="133" width="20" height="5" rx="2" fill="#E8C866" />
            </motion.g>
          </motion.svg>
        </motion.div>

        {/* ── Gold Swoosh — fades as scroll begins ── */}
        <motion.div
          className="absolute inset-0 flex items-center justify-center"
          style={{ y: ySwoosh, opacity: swooshOp }}
        >
          <svg {...svgBase} style={{ opacity: 0.16 }}>
            <path
              d="M 40 380 Q 130 420 250 405 Q 330 395 368 360"
              stroke="url(#tvSwooshGrad)"
              strokeWidth="10"
              fill="none"
              strokeLinecap="round"
            />
            <path
              d="M 55 392 Q 140 428 255 414 Q 335 404 372 375"
              stroke="#C9A84C"
              strokeWidth="4"
              fill="none"
              strokeLinecap="round"
              opacity="0.5"
            />
            <defs>
              <linearGradient id="tvSwooshGrad" x1="40" y1="380" x2="368" y2="360" gradientUnits="userSpaceOnUse">
                <stop offset="0%" stopColor="#C9A84C" stopOpacity="0.2" />
                <stop offset="50%" stopColor="#E8C866" stopOpacity="1" />
                <stop offset="100%" stopColor="#C9A84C" stopOpacity="0.3" />
              </linearGradient>
            </defs>
          </svg>
        </motion.div>

      </motion.div>{/* end scale wrapper */}

      {/* ── Golden Mist — thick at start, fully clear by 40% scroll ── */}
      <motion.div
        className="absolute inset-0"
        style={{
          background:
            "radial-gradient(ellipse 80% 80% at 50% 50%, rgba(201,168,76,0.12) 0%, rgba(10,10,10,0.5) 60%)",
          opacity: mistOpacity,
          boxShadow: "inset 0 0 180px rgba(201,168,76,0.08)",
        }}
      />
    </div>
  )
}
